(()=>{
 const q=s=>document.querySelector(s),form=q('#report-filters'),money=n=>(n/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽';let offset=0,generation=0,settings;
 async function api(path){const response=await fetch('/api/'+path,{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Не удалось загрузить отчёт.');return data}
 function node(tag,value){const e=document.createElement(tag);e.textContent=value;return e}
 async function load(){const token=++generation;q('#report-status').textContent='Загружаем отчёт…';try{const params=new URLSearchParams({from_date:form.elements.from_date.value,to_date:form.elements.to_date.value,search:form.elements.search.value.trim(),state:form.elements.state.value,debt_only:form.elements.debt_only.checked,limit:50,offset});const data=await api('finance/report?'+params);if(token!==generation)return;const totals=data.totals;q('#report-received').textContent=money(totals.received_kopecks);q('#report-earned').textContent=money(totals.earned_kopecks);q('#report-completed').textContent='Проведено уроков: '+totals.completed_lessons;q('#report-debt').textContent=money(totals.debt_kopecks);q('#report-debtors').textContent='Учеников с долгом: '+totals.debtors_count;q('#report-zone').textContent='Даты отчёта: '+data.timezone;q('#report-rows').replaceChildren();for(const row of data.items){const tr=document.createElement('tr');for(const value of [row.name+' ('+row.username+')'+(row.is_active?'':' · Архив'),money(row.received_kopecks),money(row.earned_kopecks),row.completed_lessons,money(row.balance_kopecks)])tr.append(node('td',value));if(row.debt_kopecks>0)tr.className='report-debt-row';const actions=node('td',''),history=node('a','История операций');history.href='finance.html?student_id='+row.id;actions.append(history);tr.append(actions);q('#report-rows').append(tr)}q('#report-count').textContent=data.total?'Найдено учеников: '+data.total:'По выбранным условиям учеников нет.';q('#report-previous').disabled=offset===0;q('#report-next').disabled=offset+50>=data.total;q('#report-status').textContent=''}catch(e){if(token===generation){q('#report-status').textContent=e.message;q('#report-rows').replaceChildren();q('#report-completed').textContent='';q('#report-debtors').textContent='';q('#report-count').textContent='';q('#report-previous').disabled=true;q('#report-next').disabled=true;for(const id of ['report-received','report-earned','report-debt'])q('#'+id).textContent='—'}}}
 function month(){form.elements.from_date.value=settings.today.slice(0,7)+'-01';form.elements.to_date.value=settings.today}
 form.onsubmit=e=>{e.preventDefault();offset=0;void load()};q('#report-month').onclick=()=>{month();offset=0;void load()};q('#report-previous').onclick=()=>{offset=Math.max(0,offset-50);void load()};q('#report-next').onclick=()=>{offset+=50;void load()};
 (async()=>{try{const user=await api('auth/me');if(user.role!=='admin'||user.must_change_password)throw Error('Для отчётов войдите как администратор и смените временный пароль.');window.mountAdminNavigation('finance');settings=await api('lessons/settings');month();q('#report-content').hidden=false;await load()}catch(e){q('#report-status').textContent=e.message}})();
})();
